  const campOwner = '66666666-6666-6666-6666-666666666661';
  const testerUser4 = '66666666-6666-6666-6666-666666666665';
  const testCamp = 'bbbbbbbb-aaaa-aaaa-aaaa-aaaaaaaaaaa1';

  await db.exec(`
