    testerUser4,
    `select public.submit_tester_report_v2('app_test', '${testCamp}', 'Zero reward test', 'https://storage.googleapis.com/test-bucket/reports/${testCamp}/${testerUser4}/zero.png', 5, '0123456789abcde0', '${subZeroReq}') as r;`
